insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('83a183a3-1549-43c0-a284-cb6ec29e70f3', '91864683-336f-494a-8110-0c134cf36a2c', $$f(x) = −x³ + 1½x voor x ≥ 0; top A(½√2, ½√2); lijn k: y = x, verticale lijn l door A; gebieden V en W; figuur 1$$,
   $$wiskunde-b-vwo-2026-ii-rondom-een-top-context1.png$$,
   $$Voor x ≥ 0 wordt de functie f gegeven door f(x) = −x³ + 1½x.
Het punt A(½√2, ½√2) is de top van de grafiek van f.
De lijn k met vergelijking y = x snijdt de grafiek van f in de oorsprong O en in A.
De lijn l is de verticale lijn door A.
Het gebied V is de driehoek die wordt ingesloten door k, l en de positieve x-as.
Het gebied W ligt rechts van l en wordt ingesloten door l, de grafiek van f en de positieve x-as.
In figuur 1 zijn beide gebieden grijs weergegeven.
figuur 1: de grafiek van f, de lijnen k en l en de grijze gebieden V en W$$, 'inline'),
  ('73e58292-74bf-475c-a65f-3901774db43f', '91864683-336f-494a-8110-0c134cf36a2c', $$gₚ(x) = x + |px − 1| voor p > 0; knik in A voor één waarde van p; hoek van de knik is dan 90°; figuur 2$$,
   $$wiskunde-b-vwo-2026-ii-rondom-een-top-context2.png$$,
   $$Voor p > 0 wordt de functie gₚ gegeven door gₚ(x) = x + |px − 1|.
De grafiek van gₚ heeft een knik. Voor één waarde van p bevindt deze knik zich in punt A. Zie figuur 2.
figuur 2: de grafieken van f en gₚ met de knik in A
Er geldt: in dit geval is de hoek die de knik maakt 90°.$$, 'inline'),
  ('6763b0d5-eec0-4841-96ca-057ec9265a1a', '14082956-e068-4bf8-a06e-bd80b2a7023d', $$f(x) = (2sin(x) − 1)/(4sin²(x) − 1); voor 0 ≤ x ≤ π twee perforaties$$,
   $$wiskunde-b-vwo-2026-ii-perforaties-context1.png$$,
   $$De functie f wordt gegeven door:
f(x) = (2sin(x) − 1)/(4sin²(x) − 1)
Voor 0 ≤ x ≤ π heeft de grafiek van f twee perforaties.$$, 'inline'),
  ('ae9a5c04-34d7-4043-aea7-fbc792cad879', '8d3eeb95-d9bc-49f7-8d64-9df32cad0dd7', $$thermosfles; foto; T(t) = A + (T₀ − A)·e⁻ᶜᵗ met betekenis van t, T₀, A en c$$,
   $$wiskunde-b-vwo-2026-ii-thermosflessen-context1.png$$,
   $$Een thermosfles heeft een dubbele wand. Hierdoor blijft een vloeistof die in een thermosfles wordt bewaard langere tijd warm of juist koud.
foto: een thermosfles met dop
De vloeistoftemperatuur T in een volledig gevulde en afgesloten thermosfles kan worden berekend met de formule:
T(t) = A + (T₀ − A)·e⁻ᶜᵗ
Hierbij geldt: − t is de tijd in uren nadat de thermosfles werd afgesloten. − T(t) is de vloeistoftemperatuur in °C na t uur. − T₀ is de vloeistoftemperatuur in °C bij t = 0. − A is de constante omgevingstemperatuur in °C. − c is een constante die afhangt van de kwaliteit van de thermosfles.$$, 'inline'),
  ('6f6523ce-9d1b-482c-8cae-b582ea9a1c28', '8d3eeb95-d9bc-49f7-8d64-9df32cad0dd7', $$om 9.00 uur 87 °C, om 11.30 uur 67 °C, om 14.00 uur 53 °C; stelsel vergelijkingen herleiden tot één variabele$$,
   $$wiskunde-b-vwo-2026-ii-thermosflessen-context2.png$$,
   $$Om 9.00 uur ’s ochtends wordt een volledig met vloeistof gevulde thermosfles afgesloten en in een ruimte geplaatst.
De vloeistoftemperatuur in de fles is op dat moment 87 °C.
De omgevingstemperatuur in de ruimte is constant.
De vloeistoftemperatuur in de fles is om 11.30 uur 67 °C en om 14.00 uur 53 °C.
Met bovenstaande gegevens kan een stelsel vergelijkingen worden opgesteld. Dit stelsel kan vervolgens worden herleid tot een vergelijking met één variabele.$$, 'inline'),
  ('4301ed34-d879-4497-a062-6528610577ff', '8d3eeb95-d9bc-49f7-8d64-9df32cad0dd7', $$test: T_I(t) = 20 + 75·e^(−0,2t) (Isomax) en T_Th(t) = 20 + 75·e^(−0,15t) (Therm); figuur$$,
   $$wiskunde-b-vwo-2026-ii-thermosflessen-context3.png$$,
   $$Bij een test worden twee thermosflessen van verschillende merken gevuld met een vloeistof met een temperatuur van 95 °C en in een ruimte geplaatst. Na verloop van tijd is de vloeistof in beide thermosflessen afgekoeld tot de constante omgevingstemperatuur van 20 °C.
De formule voor de vloeistoftemperatuur in de thermosfles van het merk Isomax is:
T_I(t) = 20 + 75·e^(−0,2t)
De formule voor de vloeistoftemperatuur in de thermosfles van het merk Therm is:
T_Th(t) = 20 + 75·e^(−0,15t)
In de figuur zijn de grafieken van T_I en T_Th weergegeven.
figuur: de grafieken van T_I en T_Th (T in °C tegen t in uren) dalend van 95 naar de asymptoot 20$$, 'inline'),
  ('1a79a20b-36b5-48f8-b200-3b9fc0ba92a2', '8d3eeb95-d9bc-49f7-8d64-9df32cad0dd7', $$de leverancier beweert dat het maximale temperatuurverschil vrijwel niet merkbaar is$$,
   $$wiskunde-b-vwo-2026-ii-thermosflessen-context4.png$$,
   $$De leverancier beweert dat het maximale temperatuurverschil van de vloeistoffen in beide flessen vrijwel niet merkbaar is.$$, 'inline'),
  ('01fbe897-517b-4998-a9ee-ed3413a61e4f', 'aac7b4f2-f75e-40bf-81e5-ebc894a88ca9', $$A(5 − p, 2p), B(2p, p) en C(5, 5); vectoren CA⃗ en CB⃗ voor drie waarden van p; figuur 1 met legenda; vierde positie met evenwijdige vectoren van gelijke richting$$,
   $$wiskunde-b-vwo-2026-ii-evenwijdige-vectoren-en-zwaartepunt-context1.png$$,
   $$Gegeven zijn de punten A(5 − p, 2p), B(2p, p) en C(5, 5).
In figuur 1 zijn voor drie waarden van p de vectoren CA⃗ en CB⃗ weergegeven.
figuur 1: de vectoren CA⃗ en CB⃗ voor positie 1 (gestippeld), positie 2 (dun) en positie 3 (dik)
Voor positie 2 zijn CA⃗ en CB⃗ evenwijdig en hebben ze een tegengestelde richting.
Er is een vierde positie, waarvoor de vectoren CA⃗ en CB⃗ ook evenwijdig zijn. In dat geval hebben de vectoren gelijke richting.$$, 'inline'),
  ('afdc0ee0-8a02-4afd-9d5e-63a9549d7c04', 'aac7b4f2-f75e-40bf-81e5-ebc894a88ca9', $$puntmassa's 2 in A en B en 1 in C; zwaartepunt Z ligt op lijn l; figuur 2 met plaatsvectoren$$,
   $$wiskunde-b-vwo-2026-ii-evenwijdige-vectoren-en-zwaartepunt-context2.png$$,
   $$In A en in B bevinden zich puntmassa’s met massa 2 en in C bevindt zich een puntmassa met massa 1.
Bij elke waarde van p hoort een positie van het zwaartepunt Z van de drie puntmassa’s. Deze zwaartepunten liggen op de lijn l.
In figuur 2 zijn voor een zekere waarde van p de posities van de puntmassa''s A, B en C en het bijbehorende zwaartepunt Z weergegeven.
Ook zijn voor deze waarde van p de plaatsvectoren OA⃗, OB⃗ en OC⃗ en de lijn l weergegeven.
figuur 2: de plaatsvectoren OA⃗, OB⃗ en OC⃗, het zwaartepunt Z en de gestippelde lijn l$$, 'inline'),
  ('08db105d-2fad-4c1b-b8f0-6c2f28c7a265', 'aac7b4f2-f75e-40bf-81e5-ebc894a88ca9', $$een waarde van p waarvoor x_Z = y_Z$$,
   $$wiskunde-b-vwo-2026-ii-evenwijdige-vectoren-en-zwaartepunt-context3.png$$,
   $$Er is een waarde van p waarvoor de x-coördinaat van het zwaartepunt gelijk is aan de y-coördinaat van het zwaartepunt.$$, 'inline'),
  ('37d3eda4-e733-49b6-ba3d-4a3b5e0b32d1', '97b4b4b1-0811-4eba-a6f7-b34e070d9501', $$bewegingsvergelijkingen x(t) = sin(t) − cos(3t), y(t) = cos(t) + sin(3t), 0 ≤ t ≤ 2π; baan in figuur 1$$,
   $$wiskunde-b-vwo-2026-ii-draaierig-context1.png$$,
   $$Punt P beweegt volgens de bewegingsvergelijkingen:
x(t) = sin(t) − cos(3t)
y(t) = cos(t) + sin(3t)
voor 0 ≤ t ≤ 2π
Hierbij is t de tijd in seconden. De baan van P is weergegeven in figuur 1.
figuur 1: de baan van P$$, 'inline'),
  ('f6fa3742-8a04-477c-a31d-33d2be42df8d', '97b4b4b1-0811-4eba-a6f7-b34e070d9501', $$op zes tijdstippen ligt P op de y-as$$,
   $$wiskunde-b-vwo-2026-ii-draaierig-context2.png$$,
   $$Op zes tijdstippen bevindt P zich op de y-as.$$, 'inline'),
  ('d7b5fd7b-db8a-499d-bf31-4d6ea3af8229', '97b4b4b1-0811-4eba-a6f7-b34e070d9501', $$op t = ½π en t = π gaat P door (1, −1); daar snijdt de baan zichzelf$$,
   $$wiskunde-b-vwo-2026-ii-draaierig-context3.png$$,
   $$Op de tijdstippen t = ½π en t = π gaat P door het punt (1, −1).
In (1, −1) snijdt de baan zichzelf onder een bepaalde hoek.$$, 'inline'),
  ('ac11c29c-fc89-4d61-8bce-6c7a41201ac4', '349eee3b-aeb7-4934-b0af-90ab316232cb', $$f(x) = x²·ln(½x) en g(x) = x²·ln(x); figuur; top A(2/√e, −2/e) van f, top B van g; vierkanten door A en B met zijden evenwijdig aan de assen$$,
   $$wiskunde-b-vwo-2026-ii-minimale-lengte-en-grenswaarde-context1.png$$,
   $$De functie f wordt gegeven door f(x) = x²·ln(½x) en de functie g door g(x) = x²·ln(x).
In de figuur zijn de grafieken van f en g weergegeven.
figuur: de grafieken van f en g met de toppen A en B en twee vierkanten door A en B
Punt A(2/√e, −2/e) is de top van de grafiek van f. Punt B is de top van de grafiek van g.
Door A en B worden vierkanten getekend waarvan de zijden evenwijdig zijn met de x-as en y-as. In de figuur zijn twee voorbeelden getekend van zo’n vierkant.$$, 'inline'),
  ('6df71949-c13f-4209-8346-d57b27384a16', '349eee3b-aeb7-4934-b0af-90ab316232cb', $$de zijden van de mogelijke vierkanten zijn niet even groot$$,
   $$wiskunde-b-vwo-2026-ii-minimale-lengte-en-grenswaarde-context2.png$$,
   $$De lengtes van de zijde van alle mogelijke vierkanten zijn niet even groot.$$, 'inline'),
  ('23c314c9-638a-441b-9803-a4592336b5ef', '349eee3b-aeb7-4934-b0af-90ab316232cb', $$h(x) = g(x)/f(x) nadert een grenswaarde voor toenemende x$$,
   $$wiskunde-b-vwo-2026-ii-minimale-lengte-en-grenswaarde-context3.png$$,
   $$De functie h is gegeven door h(x) = g(x)/f(x)
Voor toenemende waarden van x nadert h(x) tot een grenswaarde.$$, 'inline'),
  ('efde0d0d-69b8-4ba5-9390-49306a0221d2', '42441843-be39-4db0-9e95-0d2091a60f9c', $$f(x) = 3/√x; punten A(1, 3) en B(9, 1); figuur 1 met lijnstuk AB$$,
   $$wiskunde-b-vwo-2026-ii-een-gebroken-wortelfunctie-context1.png$$,
   $$De functie f wordt gegeven door f(x) = 3/√x.
Op de grafiek van f liggen de punten A(1, 3) en B(9, 1).
In figuur 1 zijn de grafiek van f en het lijnstuk AB weergegeven.
figuur 1: de grafiek van f en het lijnstuk AB$$, 'inline'),
  ('e70624f2-4df3-44af-b28a-c5d53ea850d9', '42441843-be39-4db0-9e95-0d2091a60f9c', $$punt tussen A en B waar de helling van f gelijk is aan die van AB; x-coördinaat is de q-de-machtswortel van p$$,
   $$wiskunde-b-vwo-2026-ii-een-gebroken-wortelfunctie-context2.png$$,
   $$Er is een punt tussen A en B op de grafiek van f waarin de helling van de grafiek van f gelijk is aan de helling van lijnstuk AB. De x-coördinaat van dat punt kan worden geschreven als q√p (de q-de-machtswortel van p), met p en q gehele getallen.$$, 'inline'),
  ('15d42f22-a7a4-4ca5-81e8-6771ff6bc827', '42441843-be39-4db0-9e95-0d2091a60f9c', $$V begrensd door de horizontale lijn door A, de verticale lijn door B en f; figuur 2; wenteling om de x-as$$,
   $$wiskunde-b-vwo-2026-ii-een-gebroken-wortelfunctie-context3.png$$,
   $$V is het gebied dat wordt begrensd door de horizontale lijn door A, de verticale lijn door B en de grafiek van f. In figuur 2 is V grijs weergegeven.
figuur 2: het grijze gebied V
Als V wordt gewenteld om de x-as ontstaat een omwentelingslichaam.$$, 'inline'),
  ('caf5f5f8-d1ef-46a4-8f21-2b381893a986', '42441843-be39-4db0-9e95-0d2091a60f9c', $$twee transformaties op f geven g door A en C, C loodrechte projectie van B op de x-as; figuur 3$$,
   $$wiskunde-b-vwo-2026-ii-een-gebroken-wortelfunctie-context4.png$$,
   $$Op de grafiek van f worden twee transformaties toegepast (dat kan op verschillende manieren). Het resultaat van deze twee transformaties is de grafiek van de functie g die door de punten A en C gaat, waarbij C de loodrechte projectie van B op de x-as is. In figuur 3 is deze situatie weergegeven.
figuur 3: de grafieken van f en g met de punten A, B en C$$, 'inline'),
  ('d112bae4-e760-418c-9706-75f64b12d0e8', '3a49f847-90a1-4dd3-871d-2e2f9b8d7757', $$cirkel c₁ met straal r₁ en middelpunt O; k raakt c₁ in A en snijdt de x-as in M met ∠AMO = 30°; cirkel c₂ met middelpunt M en straal r₂ < r₁; l door O raakt c₂ in B; figuur 1$$,
   $$wiskunde-b-vwo-2026-ii-twee-cirkels-context1.png$$,
   $$Gegeven is een cirkel c₁ met straal r₁ en middelpunt O.
Lijn k raakt c₁ in een punt A met positieve coördinaten en snijdt de positieve x-as in punt M zo dat ∠AMO = 30°.
M is het middelpunt van een cirkel c₂ met straal r₂, waarbij r₂ < r₁.
Lijn l gaat door O en raakt c₂ in punt B met positieve y-coördinaat.
Zie figuur 1.
figuur 1: de cirkels c₁ en c₂, de raaklijnen k en l en de punten A, B, C, D, E, F en M$$, 'inline'),
  ('ac4e00a5-d6c6-44fd-a3f3-c64f7ca3af7e', '3a49f847-90a1-4dd3-871d-2e2f9b8d7757', $$C = l ∩ c₁, D = k ∩ c₂, E en F loodrechte projecties op de x-as; OBM ~ OEC; CE = DF = ½r₂$$,
   $$wiskunde-b-vwo-2026-ii-twee-cirkels-context2.png$$,
   $$Lijn l snijdt c₁ in punt C en lijn k snijdt c₂ in punt D.
Punt E is de loodrechte projectie van C op de x-as.
Punt F is de loodrechte projectie van D op de x-as.
De driehoeken OBM en OEC zijn gelijkvormig.
Er geldt: CE = DF = ½r₂$$, 'inline'),
  ('c7c7c3fe-25f4-4f48-9965-7d684d7c5387', '3a49f847-90a1-4dd3-871d-2e2f9b8d7757', $$r₁ = 4 en M(8, 0); EFDC is een rechthoek; figuur 2$$,
   $$wiskunde-b-vwo-2026-ii-twee-cirkels-context3.png$$,
   $$Neem in het vervolg van deze opgave r₁ = 4 en M(8, 0).
Omdat CE en DF even lang zijn, is EFDC een rechthoek. Zie figuur 2.
figuur 2: de cirkels c₁ en c₂ met straal 4 en r₂ en de grijze rechthoek EFDC$$, 'inline'),
  ('b1b58429-cd9e-4d04-a58b-d4057a228700', '3a49f847-90a1-4dd3-871d-2e2f9b8d7757', $$oppervlakte van EFDC hangt af van r₂ en is voor één waarde maximaal$$,
   $$wiskunde-b-vwo-2026-ii-twee-cirkels-context4.png$$,
   $$De oppervlakte van rechthoek EFDC hangt af van r₂. Voor één waarde van r₂ is deze oppervlakte maximaal.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('2d6f0141-4560-4c2a-97e0-57e7ea893034', '91864683-336f-494a-8110-0c134cf36a2c', 1,
   '[{"domain": "Differentiaal- en integraalrekening", "subdomain": "Integraalrekening"}, {"domain": "Meetkunde met coördinaten", "subdomain": "Meetkundige vaardigheden"}]'::jsonb,
