  ('b29fba45-c6f7-437a-9bcc-032f73f80dad', '91864683-336f-494a-8110-0c134cf36a2c', 2,
   '[{"domain": "Functies, grafieken en vergelijkingen", "subdomain": "Standaardfuncties"}, {"domain": "Meetkunde met coördinaten", "subdomain": "Algebraïsche methoden in de vlakke meetkunde"}]'::jsonb,
   '["absolute-waardefunctie", "knik", "richtingscoëfficiënt", "loodrechte lijnen", "parameter", "bewijzen"]'::jsonb,
