   $$wiskunde-b-vwo-2026-ii-rondom-een-top-vraag2.png$$, $$4p 2 Bewijs dit.$$, array['83a183a3-1549-43c0-a284-cb6ec29e70f3', '73e58292-74bf-475c-a65f-3901774db43f']::uuid[]),
  ('a7d20c78-bda3-461c-add0-cab611db897d', '14082956-e068-4bf8-a06e-bd80b2a7023d', 3,
   '[{"domain": "Functies, grafieken en vergelijkingen", "subdomain": "Asymptoten en limietgedrag van functies"}, {"domain": "Goniometrische functies", "subdomain": "Goniometrische functies"}]'::jsonb,
   '["perforatie", "gebroken functie", "merkwaardig product", "goniometrische vergelijking", "exacte waarden", "exact berekenen"]'::jsonb,
