   $$wiskunde-b-vwo-2026-ii-perforaties-vraag3.png$$, $$4p 3 Bereken exact de coördinaten van deze twee perforaties.$$, array['6763b0d5-eec0-4841-96ca-057ec9265a1a']::uuid[]),
  ('bd664f22-16ab-4ca7-b6ad-d1236d05b553', '8d3eeb95-d9bc-49f7-8d64-9df32cad0dd7', 4,
   '[{"domain": "Functies, grafieken en vergelijkingen", "subdomain": "Vergelijkingen en ongelijkheden"}, {"domain": "Functies, grafieken en vergelijkingen", "subdomain": "Standaardfuncties"}]'::jsonb,
   '["exponentiële functie", "stelsel van vergelijkingen", "substitutie", "exponentiële vergelijking", "omgevingstemperatuur"]'::jsonb,
